import numpy as np
import scipy.sparse as sp
import scanpy as sc
import anndata as ad
from sklearn.decomposition import TruncatedSVD
from sklearn.neighbors import NearestNeighbors

def _to_csr(X):
    return X if sp.isspmatrix_csr(X) else (X.tocsr() if sp.issparse(X) else sp.csr_matrix(X))
def _row_scale_csr(X, scale):
    if not sp.issparse(X): return (X.T * scale).T
    X = _to_csr(X).copy(); X.data *= np.repeat(scale, np.diff(X.indptr)); return X
def _normalize_log1p_counts(adata):
    Xc = adata.layers['counts'] if 'counts' in adata.layers else adata.X
    Xc = _to_csr(Xc).astype(np.float32); lib = np.asarray(Xc.sum(axis=1)).ravel(); lib = np.maximum(lib, 1e-9)
    Xn = _row_scale_csr(Xc, (1e4 / lib).astype(np.float32)); Xn = Xn.tocsr().copy(); Xn.data = np.log1p(Xn.data); return Xn
def _select_features(X, adata):
    if 'batch_hvg' in adata.var.columns:
        m = adata.var['batch_hvg'].values.astype(bool)
        if 0 < m.sum() < X.shape[1]: return X[:, m]
    return X
def _pca_svd(X, n_components=50, random_state=0):
    n, g = X.shape; n_components = int(min(n_components, max(2, min(n - 1, g))))
    svd = TruncatedSVD(n_components=n_components, random_state=random_state); Z = svd.fit_transform(X); return Z.astype(np.float32)
def _design_from_batches(batches):
    b = np.asarray(batches).astype(str); uniq = np.unique(b); B = len(uniq); p = 1 + max(0, B - 1)
    X = np.zeros((b.size, p), dtype=np.float64); X[:, 0] = 1.0; m = {v:i for i,v in enumerate(uniq)}; idx = np.vectorize(m.get)(b)
    for i in range(b.size):
        j = idx[i]; if j < B - 1: X[i, 1 + j] = 1.0
    return X
def _ridge_residualize_per_pc(Z, batches, lam_r=0.6, l2=1e-3):
    X = _design_from_batches(batches); XtX = X.T @ X; p = XtX.shape[0]; XtX_reg = XtX + l2 * np.eye(p)
    XtZ = X.T @ Z; beta = np.linalg.solve(XtX_reg, XtZ); Z_pred = X @ beta; Z_res = Z - lam_r * Z_pred; return Z_res.astype(np.float32)
def _equal_quota_knn(Z, batches, k=50, k_candidates=256, metric='cosine'):
    n = Z.shape[0]; kq = min(k_candidates + 1, n); nn = NearestNeighbors(n_neighbors=kq, metric=metric, algorithm='auto')
    nn.fit(Z); d_all, idx_all = nn.kneighbors(Z, return_distance=True); d_all = d_all[:, 1:]; idx_all = idx_all[:, 1:]
    b_arr = np.asarray(batches).astype(str); uniq = np.unique(b_arr); B = len(uniq); b2i = {b:i for i,b in enumerate(uniq)}; b_idx = np.vectorize(b2i.get)(b_arr)
    rows, cols, dvals = [], [], []; base = k // B; rem = k - base * B
    for i in range(n):
        cand_idx = idx_all[i]; cand_dist = d_all[i]; cand_batch = b_idx[cand_idx]
        targets = np.full(B, base, dtype=int)
        if rem > 0:
            rot = i % B; end = min(B, rot + rem); targets[rot:end] += 1
            if end - rot < rem: targets[:(rem - (end - rot))] += 1
        chosen_mask = np.zeros(cand_idx.shape[0], dtype=bool); perb = np.zeros(B, dtype=int)
        for j in range(cand_idx.shape[0]):
            bj = cand_batch[j]
            if perb[bj] < targets[bj]:
                chosen_mask[j] = True; perb[bj] += 1
                if chosen_mask.sum() == k: break
        if chosen_mask.sum() < k:
            for j in range(cand_idx.shape[0]):
                if not chosen_mask[j]:
                    chosen_mask[j] = True
                    if chosen_mask.sum() == k: break
        sel = np.flatnonzero(chosen_mask)[:k]; chosen_idx = cand_idx[sel]; chosen_dist = cand_dist[sel]
        rows.extend([i] * chosen_idx.size); cols.extend(chosen_idx.tolist()); dvals.extend(chosen_dist.tolist())
    W_dir = sp.csr_matrix((np.ones(len(rows), dtype=np.float64), (rows, cols)), shape=(n, n))
    D_dir = sp.csr_matrix((np.asarray(dvals, dtype=np.float64), (rows, cols)), shape=(n, n))
    W = ((W_dir + W_dir.T) > 0).astype(np.float64); D = D_dir.minimum(D_dir.T); D = D + (D.T.multiply((D == 0)))
    return W.tocsr(), D.tocsr()
def eliminate_batch_effect_fn(adata: ad.AnnData) -> ad.AnnData:
    Xn = _normalize_log1p_counts(adata); Xn = _select_features(Xn, adata)
    Z_emb = _pca_svd(Xn, n_components=60, random_state=0); ad_pca = ad.AnnData(X=Z_emb.copy(), obs=adata.obs[['batch']].copy()); sc.pp.combat(ad_pca, key='batch')
    X_emb = np.asarray(ad_pca.X, dtype=np.float32)
    Z_graph = _pca_svd(Xn, n_components=50, random_state=1); Zg_corr = _ridge_residualize_per_pc(Z_graph, adata.obs['batch'].values, lam_r=0.6, l2=1e-3)
    C, D = _equal_quota_knn(Zg_corr, batches=adata.obs['batch'].values, k=50, k_candidates=256, metric='cosine')
    adata.obsm['X_emb'] = X_emb; adata.obsp['connectivities'] = C; adata.obsp['distances'] = D
    adata.uns['neighbors'] = {'connectivities_key': 'connectivities','distances_key': 'distances','params': {'n_neighbors': 50, 'method': 'equal_quota+ridge_resid','metric': 'cosine'}}
    return adata
